"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["35676"],{11400(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.codigo_duplicado","status":422,"titulo":"J\xe1 existe um valor de dom\xednio com este c\xf3digo neste fato"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.codigo_duplicado","requisitos":["UNI-REQ-0065"],"oQueAconteceu":["O administrador acrescentou um valor a um fato do cat\xe1logo (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`) com um c\xf3digo que o fato j\xe1 tem. Em cada fato, o c\xf3digo do valor \xe9 \xfanico: \xe9 o que o crit\xe9rio de aceite do UNI-REQ-0065 declara, e a API aplica a regra comparando o c\xf3digo depois de aparado. A compara\xe7\xe3o desconsidera os espa\xe7os nas pontas, mas diferencia mai\xfasculas de min\xfasculas: `eja` e `EJA` s\xe3o c\xf3digos diferentes. O valor desativado continua ocupando o seu c\xf3digo, porque o c\xf3digo de um valor nunca \xe9 removido do fato.","Na confer\xeancia comum, a recusa vem na lista `errors` da resposta, com `field` igual a `codigo`. Quando dois acr\xe9scimos do mesmo c\xf3digo, ou um acr\xe9scimo e outra altera\xe7\xe3o do mesmo fato, chegam ao mesmo tempo, o resultado depende de qual verifica\xe7\xe3o detecta a colis\xe3o primeiro: pode ser esta recusa, s\xf3 com o c\xf3digo de erro e a mensagem da resposta e sem a lista `errors` (a viola\xe7\xe3o do \xedndice \xfanico de c\xf3digo, `MutacaoDoFato.cs:52-61`), ou o conflito de concorr\xeancia do fato (409, `uniplus.configuracao.fato_candidato.conflito_de_concorrencia`, `MutacaoDoFato.cs:62-70`). Em qualquer dos casos nada \xe9 gravado. A busca do fato vem antes da confer\xeancia do corpo: com um `{id}` que n\xe3o existe, a resposta \xe9 a de fato n\xe3o encontrado (`uniplus.configuracao.fato_candidato.nao_encontrado`), e n\xe3o esta."],"comoResolver":["Escolha outro c\xf3digo para o valor novo. Se a resposta foi o conflito de concorr\xeancia, consulte o fato e confira se o valor j\xe1 foi acrescentado antes de repetir o pedido. Se o valor que voc\xea queria j\xe1 existe e est\xe1 desativado, reative-o (`POST /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}/ativacao`); se s\xf3 o texto precisa mudar, corrija a descri\xe7\xe3o ou a orienta\xe7\xe3o dele (`PUT /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}`)."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);